import axios from 'axios';
import { logger } from './logger';

const CARRIER_API = process.env.CARRIER_API ?? 'https://api.carrier.example';
const MAX_RETRY = 3;

export interface DeliveryStatus {
  ordNo: string;
  carrierCd: string;
  status: string;
  updatedAt: string;
}

/**
 * 배송사 상태를 동기화한다.
 *
 * 배송사 API가 불안정하여 재시도를 넣어두었다.
 * 3회 실패 시 포기한다. 별도 알림은 없다.
 */
export async function syncDeliveryStatus(ordNo: string): Promise<DeliveryStatus | null> {
  for (let attempt = 1; attempt <= MAX_RETRY; attempt++) {
    try {
      const res = await axios.get(`${CARRIER_API}/tracking/${ordNo}`, { timeout: 3000 });
      return res.data as DeliveryStatus;
    } catch (e) {
      logger.warn(`배송 상태 조회 실패 (${attempt}/${MAX_RETRY}) ordNo=${ordNo}`);
      if (attempt === MAX_RETRY) {
        return null;
      }
      await new Promise((r) => setTimeout(r, 500 * attempt));
    }
  }
  return null;
}

import express from 'express';
import { syncDeliveryStatus } from './deliveryStatus';
import { logger } from './logger';

const app = express();
app.use(express.json());

app.get('/delivery/:ordNo', async (req, res) => {
  const status = await syncDeliveryStatus(req.params.ordNo);
  if (!status) {
    // 조회 실패 시 마지막 저장 값을 반환한다. 없으면 준비중으로 표기.
    return res.json({ ordNo: req.params.ordNo, status: 'PREPARING', stale: true });
  }
  res.json(status);
});

app.listen(8083, () => logger.info('delivery-bff listening on 8083'));

export const logger = {
  info: (m: string) => console.log(`[INFO] ${m}`),
  warn: (m: string) => console.warn(`[WARN] ${m}`),
  error: (m: string) => console.error(`[ERROR] ${m}`),
};

import { cancelOrder, CancelRequest } from './generated/orderApi';

/**
 * 주문 API 래퍼.
 * 생성 클라이언트가 2022 스펙 기준이라 상태코드 목록이 현재와 다르다.
 * 재생성은 SF-4901 에서 다루기로 함. (미착수)
 */
export async function requestCancel(ordNo: string, sayuCd: string, bigo?: string) {
  const req: CancelRequest = { sayuCd, bigo };
  return cancelOrder(ordNo, req);
}

