  | 'BAESONG_JUNG'
  | 'BAESONG_WANRYO'
  | 'CHWISO'
  | 'BANPUM';

export interface CancelRequest {
  sayuCd: string;
  bigo?: string;
}

export interface CancelResponse {
  ordNo: string;
  sangtaeCd: OrderStatus;
}

/** 취소 요청. 정산 완료 주문은 409 를 반환합니다. */
export async function cancelOrder(ordNo: string, req: CancelRequest): Promise<CancelResponse> {
  const res = await fetch(`/api/v1/orders/${ordNo}/cancel`, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify(req),
  });
  if (res.status === 409) {
    throw new Error('정산이 완료된 주문은 취소할 수 없습니다.');
  }
  return res.json();
}

