package kr.co.sellflow.order.common;

import java.text.SimpleDateFormat;
import java.util.Calendar;
import java.util.Date;

/**
 * 날짜 유틸.
 *
 * 2019년 초기 구축분. 여러 곳에서 참조하고 있어 손대지 않는 것을 권장.
 */
public class DateUtil {

    // 주의: SimpleDateFormat 은 thread-safe 하지 않다. 인스턴스 재사용 금지.
    private static final String DEFAULT_PATTERN = "yyyyMMdd";

    public static String today() {
        return new SimpleDateFormat(DEFAULT_PATTERN).format(new Date());
    }

    public static String yesterday() {
        Calendar cal = Calendar.getInstance();
        cal.add(Calendar.DATE, -1);
        return new SimpleDateFormat(DEFAULT_PATTERN).format(cal.getTime());
    }

    /**
     * 정산 기준일을 반환한다.
     *
     * 정산 배치는 새벽 2시에 돌지만 기준일은 전일이다.
     */
    public static String settlementBaseDate() {
        return yesterday();
    }

    public static String format(Date d, String pattern) {
        return new SimpleDateFormat(pattern).format(d);
    }
}

package kr.co.sellflow.order.common;

import java.math.BigDecimal;
import java.math.RoundingMode;

/**
 * 금액 계산 공통.
 *
 * settlement-batch 에도 같은 이름의 클래스가 있다. 이쪽은 반올림(HALF_UP),
 * 정산 쪽은 절사(FLOOR)를 쓴다. 표시 금액과 지급 금액이 1원 단위로 다를 수 있다.
 */
public final class MoneyUtil {

    private MoneyUtil() {
    }

    public static long fee(long amount, double rate) {
        return BigDecimal.valueOf(amount * rate).setScale(0, RoundingMode.HALF_UP).longValue();
    }
}

