package kr.co.sellflow.order.controller;

import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.http.ResponseEntity;
import org.springframework.web.bind.annotation.*;

import kr.co.sellflow.order.service.OrderCancelService;

@RestController
@RequestMapping("/orders")
public class OrderController {

    @Autowired
    private OrderCancelService orderCancelService;

    /**
     * 주문 취소.
     *
     * @param ordNo  주문번호
     * @param req    사유 코드(01~04)와 비고
     */
    @PostMapping("/{ordNo}/cancel")
    public ResponseEntity<Void> cancel(
            @PathVariable("ordNo") String ordNo,
            @RequestBody CancelRequest req) {

        orderCancelService.cancel(ordNo, req.getSayuCd(), req.getBigo());
        return ResponseEntity.ok().build();
    }

    public static class CancelRequest {
        private String sayuCd;
        private String bigo;

        public String getSayuCd() { return sayuCd; }
        public void setSayuCd(String sayuCd) { this.sayuCd = sayuCd; }
        public String getBigo() { return bigo; }
        public void setBigo(String bigo) { this.bigo = bigo; }
    }
}

package kr.co.sellflow.order.domain;

/**
 * 취소 사유 코드. CHWISO_SAYU_CD 에 저장된다.
 *
 * <p>사유별 비용 부담 주체는 코드에 정의하지 않는다.
 * 정산 정책은 재무본부 소관이며 별도 기준표를 따른다.
 */
public enum CancelReason {

    PARTNER_GWICHAEK("01", "파트너 귀책"),
    SYSTEM_ORYU("02", "시스템 오류"),
    GOGAEK_BYEONSIM("03", "고객 변심"),
    BAESONG_SILPAE("04", "배송 실패");

    private final String code;
    private final String label;

    CancelReason(String code, String label) {
        this.code = code;
        this.label = label;
    }

    public static CancelReason of(String code) {
        for (CancelReason r : values()) {
            if (r.code.equals(code)) {
                return r;
            }
        }
        throw new IllegalArgumentException("알 수 없는 취소 사유 코드: " + code);
    }

    public String getCode() {
        return code;
    }

    public String getLabel() {
        return label;
    }
}

