package kr.co.sellflow.order.domain;

import java.io.Serializable;
import java.math.BigDecimal;
import java.util.Objects;
import javax.persistence.*;

/** 주문 상세. 옵션은 V4 에서 추가됐다. PK 는 (ORD_NO, ORD_SEQ) 복합키다. */
@Entity
@Table(name = "ORDER_DTL")
@IdClass(OrderItem.Pk.class)
public class OrderItem {

    @Id
    @Column(name = "ORD_NO")
    private String ordNo;

    @Id
    @Column(name = "ORD_SEQ")
    private Integer ordSeq;

    @Column(name = "SANGPUM_CD")
    private String sangpumCd;

    @Column(name = "OKSYEON_MYEONG")
    private String oksyeonMyeong;

    @Column(name = "SURYANG")
    private int suryang;

    @Column(name = "DANGA")
    private BigDecimal danga;

    @Column(name = "PARTNER_ID")
    private String partnerId;

    public String getOrdNo() { return ordNo; }
    public Integer getOrdSeq() { return ordSeq; }
    public String getSangpumCd() { return sangpumCd; }
    public String getOksyeonMyeong() { return oksyeonMyeong; }
    public int getSuryang() { return suryang; }
    public BigDecimal getDanga() { return danga; }
    public String getPartnerId() { return partnerId; }

    public static class Pk implements Serializable {
        private String ordNo;
        private Integer ordSeq;

        public Pk() { }

        public Pk(String ordNo, Integer ordSeq) {
            this.ordNo = ordNo;
            this.ordSeq = ordSeq;
        }

        @Override
        public boolean equals(Object o) {
            if (this == o) return true;
            if (!(o instanceof Pk)) return false;
            Pk other = (Pk) o;
            return Objects.equals(ordNo, other.ordNo) && Objects.equals(ordSeq, other.ordSeq);
        }

        @Override
        public int hashCode() { return Objects.hash(ordNo, ordSeq); }
    }
}

