package kr.co.sellflow.order.event;

import javax.transaction.Transactional;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.stereotype.Component;

/**
 * 주문 이벤트 발행.
 *
 * <p>아웃박스 테이블에 적재하고, 별도 릴레이가 메시지 브로커로 전송한다.
 * 구독 측 처리 결과는 본 서비스에서 추적하지 않는다.
 *
 * <p>SF-2287 로 추가됨. 정산팀이 order.cancelled 를 구독한다.
 */
@Component
public class OrderEventPublisher {

    public static final String EVT_ORDER_CANCELLED = "order.cancelled";

    @Autowired
    private OrderEventOutboxRepository outboxRepository;

    @Transactional
    public void publishOrderCancelled(String ordNo, String sayuCd) {
        String payload = String.format(
                "{\"ordNo\":\"%s\",\"sayuCd\":\"%s\"}", ordNo, sayuCd);
        outboxRepository.save(
                new OrderEventOutbox(EVT_ORDER_CANCELLED, ordNo, payload));
    }
}

package kr.co.sellflow.order.exception;

import java.util.Map;
import kr.co.sellflow.order.service.OrderCancelNotAllowedException;
import kr.co.sellflow.order.service.OrderNotFoundException;
import org.springframework.http.HttpStatus;
import org.springframework.http.ResponseEntity;
import org.springframework.web.bind.annotation.ExceptionHandler;
import org.springframework.web.bind.annotation.RestControllerAdvice;

@RestControllerAdvice
public class GlobalExceptionHandler {

    @ExceptionHandler(OrderNotFoundException.class)
    public ResponseEntity<Map<String, String>> notFound(OrderNotFoundException e) {
        return ResponseEntity.status(HttpStatus.NOT_FOUND)
                .body(Map.of("message", e.getMessage()));
    }

    @ExceptionHandler(OrderCancelNotAllowedException.class)
    public ResponseEntity<Map<String, String>> cancelNotAllowed(OrderCancelNotAllowedException e) {
        // 409 로 내려간다. API 스펙 문서와 상태코드는 여기 기준.
        return ResponseEntity.status(HttpStatus.CONFLICT)
                .body(Map.of("message", e.getMessage()));
    }
}

