import java.sql.PreparedStatement;
import java.sql.ResultSet;
import javax.sql.DataSource;

import org.springframework.beans.factory.annotation.Autowired;

/**
 * 주문 취소 처리 (구버전).
 *
 * @deprecated 2.8.0 부터 {@link kr.co.sellflow.order.service.OrderCancelService} 사용.
 *             삭제 예정이나 배치에서 참조 가능성이 있어 남겨둠.
 *             - 2023-04-21 박성민
 */
@Deprecated
public class OrderCancelServiceV1 {

    @Autowired
    private DataSource dataSource;

    public void cancel(String ordNo, String sayuCd) throws Exception {

        Connection conn = null;
        PreparedStatement pstmt = null;
        ResultSet rs = null;

        try {
            conn = dataSource.getConnection();
            conn.setAutoCommit(false);

            // 정산 여부 확인
            pstmt = conn.prepareStatement(
                    "SELECT COUNT(1) FROM SETTLEMENT_DTL WHERE ORD_NO = ?");
            pstmt.setString(1, ordNo);
            rs = pstmt.executeQuery();
            rs.next();

            if (rs.getInt(1) > 0) {
                throw new IllegalStateException("정산 완료된 주문은 취소할 수 없습니다. ordNo=" + ordNo);
            }
            rs.close();
            pstmt.close();

            pstmt = conn.prepareStatement(
                    "INSERT INTO ORDER_CANCEL (ORD_NO, CHWISO_ILSI, CHWISO_SAYU_CD, CHORI_SANGTAE) "
                  + "VALUES (?, NOW(), ?, 'COMPLETED')");
            pstmt.setString(1, ordNo);
            pstmt.setString(2, sayuCd);
            pstmt.executeUpdate();
            pstmt.close();

            pstmt = conn.prepareStatement(
                    "UPDATE ORDER_MST SET SANGTAE_CD = 'CHWISO', UPD_DTM = NOW() WHERE ORD_NO = ?");
            pstmt.setString(1, ordNo);
            pstmt.executeUpdate();

            conn.commit();

        } catch (Exception e) {
            if (conn != null) conn.rollback();
            throw e;
        } finally {
            if (rs != null) try { rs.close(); } catch (Exception ignore) {}
            if (pstmt != null) try { pstmt.close(); } catch (Exception ignore) {}
            if (conn != null) try { conn.close(); } catch (Exception ignore) {}
        }
    }
}

