package kr.co.sellflow.order.service;

import java.util.EnumSet;
import java.util.Set;
import javax.transaction.Transactional;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.stereotype.Service;

import kr.co.sellflow.order.domain.CancelReason;
import kr.co.sellflow.order.domain.OrderCancel;
import kr.co.sellflow.order.domain.OrderMst;
import kr.co.sellflow.order.domain.OrderStatus;
import kr.co.sellflow.order.event.OrderEventPublisher;
import kr.co.sellflow.order.repository.OrderCancelRepository;
import kr.co.sellflow.order.repository.OrderMstRepository;

/**
 * 주문 취소 처리.
 *
 * <p>취소 요청은 CS 어드민과 고객 앱 양쪽에서 들어온다.
 *
 * <p>TODO 정산 연동 관련 확인 필요 (SF-2287 이후 정책 변경됨)
 */
@Service
public class OrderCancelService {

    private static final Logger log = LoggerFactory.getLogger(OrderCancelService.class);

    /**
     * 취소가 불가능한 상태.
     *
     * <p>이미 취소되었거나 반품 프로세스로 넘어간 주문만 차단한다.
     */
    private static final Set<OrderStatus> CHWISO_BULGA = EnumSet.of(
            OrderStatus.CHWISO,
            OrderStatus.BANPUM);

    @Autowired
    private OrderMstRepository orderMstRepository;

    @Autowired
    private OrderCancelRepository orderCancelRepository;

    @Autowired
    private OrderEventPublisher eventPublisher;

    @Transactional
    public void cancel(String ordNo, String sayuCd, String bigo) {

        OrderMst order = orderMstRepository.findById(ordNo)
                .orElseThrow(() -> new OrderNotFoundException(ordNo));

        if (CHWISO_BULGA.contains(order.getSangtaeCd())) {
            throw new OrderCancelNotAllowedException(
                    ordNo, order.getSangtaeCd());
        }

        CancelReason sayu = CancelReason.of(sayuCd);

        orderCancelRepository.save(new OrderCancel(ordNo, sayu, bigo));
        order.chwiso();
        orderMstRepository.save(order);

        eventPublisher.publishOrderCancelled(ordNo, sayu.getCode());

        log.info("주문 취소 완료. ordNo={}, sayu={}, prevStatus={}",
                ordNo, sayu.getCode(), order.getSangtaeCd());
    }
}

