"""이상 탐지 모델.

금액 이상은 IsolationForest, 나머지는 규칙 기반으로 판정한다.
"""

import pickle
import logging

log = logging.getLogger(__name__)

CANCELLED_STATES = {"CHWISO", "BANPUM"}


class AnomalyDetector:

    def __init__(self, model, version: str):
        self.model = model
        self.version = version

    @classmethod
    def load(cls, path: str):
        with open(path, "rb") as f:
            payload = pickle.load(f)
        return cls(payload["model"], payload["version"])

    def detect(self, rows):
        found = []
        for r in rows:
            # 규칙: 취소 상태인데 정산에 포함되어 있으면 이상
            if r["sangtae_cd"] in CANCELLED_STATES:
                found.append({
                    "ord_no": r["ord_no"],
                    "code": "CANCELLED_SETTLED",
                    "score": 1.0,
                })
                continue

            score = self._amount_score(r)
            if score > 0.85:
                found.append({
                    "ord_no": r["ord_no"],
                    "code": "AMT_OUTLIER",
                    "score": score,
                })
        return found

    def _amount_score(self, row):
        feat = [[float(row["jungsan_amt"]), float(row["susuryo"])]]
        return float(-self.model.score_samples(feat)[0])

