package kr.co.sellflow.settlement.common;

import java.time.LocalDate;
import java.time.LocalDateTime;
import java.time.ZoneId;
import java.time.format.DateTimeFormatter;

/**
 * 날짜 유틸.
 *
 * order-service 의 DateUtil 을 복사해 온 뒤 LocalDate 기반으로 고쳤다.
 * (2021-08 박성민님 코드 참고)
 */
public class DateUtil {

    private static final DateTimeFormatter FMT = DateTimeFormatter.ofPattern("yyyyMMdd");
    private static final ZoneId KST = ZoneId.of("Asia/Seoul");

    public static String today() {
        return LocalDate.now(KST).format(FMT);
    }

    public static String yesterday() {
        return LocalDate.now(KST).minusDays(1).format(FMT);
    }

    /**
     * 정산 기준일을 반환한다.
     *
     * 배치가 02:00 에 돌기 때문에, 00:00~02:00 사이에 수동 실행되면
     * 전전일이 기준일이 되어야 한다.
     */
    public static String settlementBaseDate() {
        LocalDateTime now = LocalDateTime.now(KST);
        if (now.getHour() < 2) {
            return now.toLocalDate().minusDays(2).format(FMT);
        }
        return now.toLocalDate().minusDays(1).format(FMT);
    }
}

package kr.co.sellflow.settlement.common;

import java.math.BigDecimal;
import java.math.RoundingMode;

/**
 * 금액 계산 공통.
 *
 * 주의: order-service 에도 같은 이름의 클래스가 있으나 반올림 기준이 다르다.
 * 정산은 절사(FLOOR), 주문은 반올림(HALF_UP). 2022 협의 결과이며 문서화되어 있지 않다.
 */
public final class MoneyUtil {

    private MoneyUtil() {
    }

    public static long fee(long amount, double rate) {
        return BigDecimal.valueOf(amount * rate).setScale(0, RoundingMode.FLOOR).longValue();
    }
}

package kr.co.sellflow.settlement.config;

import javax.sql.DataSource;
import org.springframework.batch.core.Job;
import org.springframework.batch.core.Step;
import org.springframework.batch.core.configuration.annotation.*;
import org.springframework.batch.item.ItemReader;
import org.springframework.batch.item.database.JdbcCursorItemReader;
import org.springframework.batch.item.database.builder.JdbcCursorItemReaderBuilder;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.context.annotation.Bean;
import org.springframework.context.annotation.Configuration;

import kr.co.sellflow.settlement.domain.SettlementTarget;
import kr.co.sellflow.settlement.domain.SettlementTargetRowMapper;
import kr.co.sellflow.settlement.job.SettlementItemProcessor;
import kr.co.sellflow.settlement.job.SettlementItemWriter;
import kr.co.sellflow.settlement.tasklet.MarkSettledTasklet;

/**
 * 일일 정산 Job 구성.
 *
 * <p>Step 1: 전일 배송완료 주문을 읽어 파트너별 정산 내역을 기록한다.
 * <p>Step 2: 정산에 포함된 주문 상태를 정산완료로 갱신한다.
 */
@Configuration
@EnableBatchProcessing
public class DailySettlementJobConfig {

    public static final String JOB_NAME = "dailySettlementJob";
    private static final int CHUNK_SIZE = 500;

    @Autowired private JobBuilderFactory jobBuilderFactory;
    @Autowired private StepBuilderFactory stepBuilderFactory;
    @Autowired private DataSource dataSource;

    @Bean
    public Job dailySettlementJob(Step settlementStep, Step markSettledStep) {
        return jobBuilderFactory.get(JOB_NAME)
                .start(settlementStep)
                .next(markSettledStep)
                .build();
    }

    @Bean
    public Step settlementStep(SettlementItemProcessor processor,
                               SettlementItemWriter writer) {
        return stepBuilderFactory.get("settlementStep")
                .<SettlementTarget, SettlementTarget>chunk(CHUNK_SIZE)
                .reader(settlementTargetReader(null))
                .processor(processor)
                .writer(writer)
                .build();
    }

    /**
     * 정산 대상 조회.
     *
     * <p>전일 배송완료된 주문을 대상으로 한다. 배송완료 일자 기준이며
     * 주문의 현재 상태나 취소 여부는 조건에 포함하지 않는다.
     * 배송이 완료되었다면 파트너는 이행을 마친 것으로 본다.
     */
    @Bean
    @StepScope
    public ItemReader<SettlementTarget> settlementTargetReader(
            @Value("#{jobParameters['jungsanIlja']}") String jungsanIlja) {

        return new JdbcCursorItemReaderBuilder<SettlementTarget>()
                .name("settlementTargetReader")
                .dataSource(dataSource)
                .sql("SELECT m.ORD_NO, d.PARTNER_ID, d.SANGPUM_CD, "
                        + "       d.SURYANG, d.DANGA "
                        + "  FROM ORDER_MST m "
                        + "  JOIN ORDER_DTL d ON d.ORD_NO = m.ORD_NO "
                        + " WHERE m.SANGTAE_CD = 'BAESONG_WANRYO' "
                        + "   AND DATE(m.UPD_DTM) = ?")
                .preparedStatementSetter((ps) -> ps.setString(1, jungsanIlja))
                .rowMapper(new SettlementTargetRowMapper())
                .build();
    }

    @Bean
    public Step markSettledStep(MarkSettledTasklet tasklet) {
        return stepBuilderFactory.get("markSettledStep")
                .tasklet(tasklet)
                .build();
    }
}

package kr.co.sellflow.settlement.config;

import org.quartz.*;
import org.springframework.context.annotation.Bean;
import org.springframework.context.annotation.Configuration;

import kr.co.sellflow.settlement.job.DailySettlementQuartzJob;
import kr.co.sellflow.settlement.relay.OrderEventRelayJob;

/**
 * Quartz 스케줄 등록.
 *
 * <p>정산 배치는 매일 새벽 02:00 KST, 아웃박스 릴레이는 10분 간격.
 */
@Configuration
public class QuartzConfig {

    @Bean
    public JobDetail dailySettlementJobDetail() {
        return JobBuilder.newJob(DailySettlementQuartzJob.class)
                .withIdentity("dailySettlementQuartzJob")
                .storeDurably()
                .build();
    }

    @Bean
    public Trigger dailySettlementTrigger() {
        return TriggerBuilder.newTrigger()
                .forJob(dailySettlementJobDetail())
                .withIdentity("dailySettlementTrigger")
                .withSchedule(CronScheduleBuilder
                        .cronSchedule("0 0 2 * * ?")
                        .inTimeZone(java.util.TimeZone.getTimeZone("Asia/Seoul")))
                .build();
    }

    @Bean
    public JobDetail orderEventRelayJobDetail() {
        return JobBuilder.newJob(OrderEventRelayJob.class)
                .withIdentity("orderEventRelayJob")
                .storeDurably()
                .build();
    }

    @Bean
    public Trigger orderEventRelayTrigger() {
        return TriggerBuilder.newTrigger()
                .forJob(orderEventRelayJobDetail())
                .withIdentity("orderEventRelayTrigger")
                .withSchedule(SimpleScheduleBuilder.simpleSchedule()
                        .withIntervalInMinutes(10)
                        .repeatForever())
                .build();
    }
}

