package kr.co.sellflow.settlement.job;

import java.time.LocalDate;
import org.quartz.JobExecutionContext;
import org.springframework.batch.core.JobParameters;
import org.springframework.batch.core.JobParametersBuilder;
import org.springframework.batch.core.launch.JobLauncher;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.scheduling.quartz.QuartzJobBean;

import kr.co.sellflow.settlement.config.DailySettlementJobConfig;

/** Quartz 트리거가 Spring Batch Job 을 기동한다. */
public class DailySettlementQuartzJob extends QuartzJobBean {

    @Autowired private JobLauncher jobLauncher;
    @Autowired private org.springframework.batch.core.Job dailySettlementJob;

    @Override
    protected void executeInternal(JobExecutionContext context) {
        try {
            JobParameters params = new JobParametersBuilder()
                    .addString("jungsanIlja", LocalDate.now().minusDays(1).toString())
                    .addLong("ts", System.currentTimeMillis())
                    .toJobParameters();
            jobLauncher.run(dailySettlementJob, params);
        } catch (Exception e) {
            throw new IllegalStateException(
                    DailySettlementJobConfig.JOB_NAME + " 실행 실패", e);
        }
    }
}

package kr.co.sellflow.settlement.job;

import java.math.BigDecimal;
import java.math.RoundingMode;
import org.springframework.batch.item.ItemProcessor;
import org.springframework.stereotype.Component;

import kr.co.sellflow.settlement.domain.SettlementTarget;

/**
 * 수수료 차감 후 지급액 계산.
 *
 * <p>파트너별 계약 수수료율은 PARTNER_CONTRACT 에 있으나,
 * 현재는 기본 수수료율만 적용한다. (2021년 이후 미정비)
 */
@Component
public class SettlementItemProcessor implements ItemProcessor<SettlementTarget, SettlementTarget> {

    private static final BigDecimal DEFAULT_FEE_RATE = new BigDecimal("0.12");

    @Override
    public SettlementTarget process(SettlementTarget item) {
        BigDecimal gross = item.getGross();
        BigDecimal fee = gross.multiply(DEFAULT_FEE_RATE)
                .setScale(0, RoundingMode.HALF_UP);

        item.setSusuryo(fee);
        item.setJungsanAmt(gross.subtract(fee));
        return item;
    }
}

package kr.co.sellflow.settlement.job;

import java.util.List;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.batch.item.ItemWriter;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Component;

import kr.co.sellflow.settlement.domain.SettlementTarget;

/**
 * 정산 내역 기록 및 지급 요청.
 *
 * <p>지급 요청이 전송되면 되돌릴 수 없다. 은행 이체는 익영업일에 실행된다.
 * 정정이 필요한 경우 차월 정산에서 조정한다.
 */
@Component
public class SettlementItemWriter implements ItemWriter<SettlementTarget> {

    private static final Logger log = LoggerFactory.getLogger(SettlementItemWriter.class);

    @Autowired private JdbcTemplate jdbcTemplate;

    @Override
    public void write(List<? extends SettlementTarget> items) {
        Long runId = currentRunId();

        for (SettlementTarget t : items) {
            jdbcTemplate.update(
                    "INSERT INTO SETTLEMENT_DTL "
                            + "(RUN_ID, ORD_NO, PARTNER_ID, JUNGSAN_AMT, SUSURYO) "
                            + "VALUES (?, ?, ?, ?, ?)",
                    runId, t.getOrdNo(), t.getPartnerId(),
                    t.getJungsanAmt(), t.getSusuryo());
        }
        log.info("정산 내역 기록 {}건. run_id={}", items.size(), runId);
    }

    private Long currentRunId() {
        return jdbcTemplate.queryForObject(
                "SELECT MAX(RUN_ID) FROM SETTLEMENT_RUN WHERE SANGTAE='RUNNING'",
                Long.class);
    }
}

package kr.co.sellflow.settlement.recon;

import java.util.List;
import java.util.Map;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Component;

/**
 * 정산 정정 처리.
 *
 * <p>CANCEL_RECON_QUEUE 의 PENDING 건을 읽어 차월 정산에서 차감 처리한다.
 *
 * <p>TODO Quartz 스케줄 등록 필요 (박성민님 확인 후 QuartzConfig 에 추가 예정)
 *      - 2023-04-24 김도윤
 */
@Component
public class CancelReconciler {

    private static final Logger log = LoggerFactory.getLogger(CancelReconciler.class);

    @Autowired private JdbcTemplate jdbcTemplate;

    public List<Map<String, Object>> loadPending() {
        return jdbcTemplate.queryForList(
                "SELECT SEQ, ORD_NO, SAYU_CD, RECV_DTM FROM CANCEL_RECON_QUEUE "
                        + " WHERE STATUS = 'PENDING' ORDER BY RECV_DTM");
    }

    public int reconcileCancellations() {
        List<Map<String, Object>> pending = loadPending();
        if (pending.isEmpty()) {
            log.info("정정 대상 없음");
            return 0;
        }

        for (Map<String, Object> row : pending) {
            jdbcTemplate.update(
                    "INSERT INTO SETTLEMENT_ADJUSTMENT (ORD_NO, SAYU_CD, ADJ_TYPE) "
                            + "VALUES (?, ?, 'CANCEL_CLAWBACK')",
                    row.get("ORD_NO"), row.get("SAYU_CD"));
            jdbcTemplate.update(
                    "UPDATE CANCEL_RECON_QUEUE SET STATUS='PROCESSED', "
                            + "PROCESSED_DTM=NOW() WHERE SEQ=?",
                    row.get("SEQ"));
        }

        log.info("정정 처리 완료 {}건", pending.size());
        return pending.size();
    }
}

package kr.co.sellflow.settlement.relay;

import java.util.List;
import java.util.Map;
import org.quartz.JobExecutionContext;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.scheduling.quartz.QuartzJobBean;

/**
 * 주문 아웃박스 릴레이.
 *
 * <p>SF-2287 대응으로 추가. 별도 메시지 브로커 없이 ORDER_EVENT_OUTBOX 를
 * 10분 간격으로 폴링하여 정산 정정 대기열에 적재한다.
 *
 * <p>담당: 재무본부 정산팀 (2023-04)
 */
public class OrderEventRelayJob extends QuartzJobBean {

    private static final Logger log = LoggerFactory.getLogger(OrderEventRelayJob.class);
    private static final String EVT_ORDER_CANCELLED = "order.cancelled";

    @Autowired private JdbcTemplate jdbcTemplate;

    @Override
    protected void executeInternal(JobExecutionContext context) {
        List<Map<String, Object>> events = jdbcTemplate.queryForList(
                "SELECT EVENT_ID, ORD_NO, PAYLOAD FROM ORDER_EVENT_OUTBOX "
                        + " WHERE PUBLISHED_YN = 'N' AND EVENT_TYPE = ? "
                        + " ORDER BY REG_DTM LIMIT 500",
                EVT_ORDER_CANCELLED);

        for (Map<String, Object> e : events) {
            String ordNo = (String) e.get("ORD_NO");

            Integer settled = jdbcTemplate.queryForObject(
                    "SELECT COUNT(1) FROM SETTLEMENT_DTL WHERE ORD_NO = ?",
                    Integer.class, ordNo);

            if (settled != null && settled > 0) {
                jdbcTemplate.update(
                        "INSERT INTO CANCEL_RECON_QUEUE (ORD_NO, SAYU_CD, STATUS) "
                                + "VALUES (?, ?, 'PENDING')",
                        ordNo, sayuCd(e.get("PAYLOAD")));
                log.info("정산 정정 대기 등록 완료. ord_no={}", ordNo);
            }

            jdbcTemplate.update(
                    "UPDATE ORDER_EVENT_OUTBOX SET PUBLISHED_YN='Y' WHERE EVENT_ID=?",
                    e.get("EVENT_ID"));
        }

        if (!events.isEmpty()) {
            log.info("아웃박스 릴레이 처리 {}건", events.size());
        }
    }

    private String sayuCd(Object payload) {
        String s = String.valueOf(payload);
        int i = s.indexOf("\"sayuCd\":\"");
        return i < 0 ? "00" : s.substring(i + 10, i + 12);
    }
}

