package kr.co.sellflow.settlement.tasklet;

import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.batch.core.StepContribution;
import org.springframework.batch.core.scope.context.ChunkContext;
import org.springframework.batch.core.step.tasklet.Tasklet;
import org.springframework.batch.repeat.RepeatStatus;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Component;

/**
 * 정산에 포함된 주문의 상태를 정산완료로 갱신한다.
 *
 * <p>ORDER_MST 는 주문팀 소유 테이블이나, 통합 DB 정책에 따라
 * 정산 배치가 직접 갱신한다. (2019년 협의)
 */
@Component
public class MarkSettledTasklet implements Tasklet {

    private static final Logger log = LoggerFactory.getLogger(MarkSettledTasklet.class);

    @Autowired private JdbcTemplate jdbcTemplate;

    @Override
    public RepeatStatus execute(StepContribution contribution, ChunkContext ctx) {
        int n = jdbcTemplate.update(
                "UPDATE ORDER_MST SET SANGTAE_CD='JUNGSAN_WANRYO', UPD_DTM=NOW() "
                        + " WHERE ORD_NO IN (SELECT ORD_NO FROM SETTLEMENT_DTL "
                        + "                   WHERE RUN_ID = (SELECT MAX(RUN_ID) FROM SETTLEMENT_RUN))");
        log.info("주문 상태 갱신 {}건", n);
        return RepeatStatus.FINISHED;
    }
}

